def b():
    class CustomArgument(click.Argument): pass
    @click.command()
    @click.argument('a', cls=CustomArgument)
    @click.argument('b', cls=CustomArgument)
    def cli(a, b): pass
    assert type(cli.params[0]) is CustomArgument, type(cli.params[0])
    assert type(cli.params[1]) is CustomArgument, type(cli.params[1])
